		inv.GenericFindings = append(inv.GenericFindings, sr.Inventory.GenericFindings...)
		inv.Packages = append(inv.Packages, sr.Inventory.Packages...)
		inv.PackageVulns = append(inv.PackageVulns, sr.Inventory.PackageVulns...)
