// TestBuildVulnerabilityResultsWithEmptyLicense ensures a package with an empty
// license field does not panic when a license allowlist is configured, and is
// instead recorded as a license violation.
func TestBuildVulnerabilityResultsWithEmptyLicense(t *testing.T) {
	t.Parallel()

	scanResults := &results.ScanResults{
		Inventory: inventory.Inventory{
			Packages: []*extractor.Package{
				{
					Name:     "no-license-pkg",
					PURLType: purl.TypeNPM,
					Plugins:  []string{packagelockjson.Name},
					Version:  "1.0.0",
					Location: extractor.LocationFromPath("dir/package-lock.json"),
					Licenses: []string{""},
					ScanRoot: "root/",
				},
			},
		},
		ConfigManager: config.Manager{},
	}

	got := buildVulnerabilityResults(ScannerActions{
		ShowAllPackages:       true,
		ScanLicensesAllowlist: []string{"MIT"},
		CallAnalysisStates:    map[string]bool{},
	}, scanResults)

	if len(got.Results) != 1 {
		t.Fatalf("expected 1 package source, got %d", len(got.Results))
	}

	packages := got.Results[0].Packages
	if len(packages) != 1 {
		t.Fatalf("expected 1 package, got %d", len(packages))
	}

	if violations := packages[0].LicenseViolations; !slices.Equal(violations, []models.License{""}) {
		t.Errorf("expected the empty license to be reported as a violation, got %v", violations)
	}
}

package osvscanner

import (
	"cmp"
	"fmt"

	"github.com/google/osv-scalibr/extractor"
)

// InventorySort is a comparator function for Inventories, to be used in
// tests with cmp.Diff to disregard the order in which the Inventories
// are reported.
func inventorySort(a, b *extractor.Package) int {
	aLoc := a.Location.PathOrEmpty()
	bLoc := b.Location.PathOrEmpty()

	var aExtr, bExtr string
	var aPURL, bPURL string

	aPURLStruct := a.PURL()
	bPURLStruct := b.PURL()

	if aPURLStruct != nil {
		aPURL = aPURLStruct.String()
	}

	if bPURLStruct != nil {
		bPURL = bPURLStruct.String()
	}

	aSourceCode := fmt.Sprintf("%v", a.SourceCode)
	bSourceCode := fmt.Sprintf("%v", b.SourceCode)

	return cmp.Or(
		cmp.Compare(aLoc, bLoc),
		cmp.Compare(a.Name, b.Name),
		cmp.Compare(a.Version, b.Version),
		cmp.Compare(aSourceCode, bSourceCode),
		cmp.Compare(aExtr, bExtr),
		cmp.Compare(aPURL, bPURL),
	)
}
