// Find the git repository root by looking for go.mod
func findRepoRoot() string {
	dir, err := os.Getwd()
	if err != nil {
		return ""
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}

	return ""
}

func getSafeLocalDBPath(repoRoot, ecosystem string) (string, error) {
	if ecosystem == "" || ecosystem == "." || strings.Contains(ecosystem, "..") || strings.ContainsAny(ecosystem, `/\`) {
		return "", fmt.Errorf("invalid ecosystem name: %q", ecosystem)
	}

	baseDir := filepath.Join(repoRoot, offlineDBRelativePath)
	targetPath := filepath.Join(baseDir, ecosystem)

	rel, err := filepath.Rel(baseDir, targetPath)
	if err != nil || strings.HasPrefix(rel, "..") || rel == "." {
		return "", fmt.Errorf("ecosystem path escapes base directory: %q", ecosystem)
	}

	return targetPath, nil
}

func (t *vcrResponseNormalizingTransport) handleOfflineDBDownload(req *http.Request) (*http.Response, error) {
	repoRoot := findRepoRoot()
	ecosystem := filepath.Base(filepath.Dir(req.URL.Path)) // e.g. "Alpine", "Packagist"
	localDBPath, err := getSafeLocalDBPath(repoRoot, ecosystem)
	if err != nil {
		return nil, err
	}

	if os.Getenv("VCR_UPDATE_OFFLINE_DBS") == "true" {
		if err := t.updateOfflineDB(req.URL.String(), localDBPath, ecosystem); err != nil {
			return nil, err
		}
	}

	zipBytes, err := buildZipInMemory(ecosystem)
	if err != nil {
		return nil, fmt.Errorf("failed to build local offline database zip for %s: %w", ecosystem, err)
	}

	resp := &http.Response{
		Status:        "200 OK",
		StatusCode:    http.StatusOK,
		Proto:         "HTTP/1.1",
		ProtoMajor:    1,
		ProtoMinor:    1,
		Body:          io.NopCloser(bytes.NewBuffer(zipBytes)),
		ContentLength: int64(len(zipBytes)),
		Header:        make(http.Header),
		Request:       req,
	}
	resp.Header.Set("Content-Type", "application/zip")
	resp.Header.Set("Content-Length", strconv.Itoa(len(zipBytes)))
	resp.Header.Set("X-Goog-Hash", "crc32c="+computeCRC32CBase64(zipBytes))

	return resp, nil
}

func computeCRC32CBase64(data []byte) string {
	checksum := crc32.Checksum(data, crc32.MakeTable(crc32.Castagnoli))
	buf := make([]byte, 4)
	binary.BigEndian.PutUint32(buf, checksum)

	return base64.StdEncoding.EncodeToString(buf)
}

