			}
		}
	}

	result := slices.Collect(maps.Values(uniqueVulns))
	slices.SortFunc(result, func(a, b *inventory.PackageVuln) int {
		return cmp.Or(
			inventorySort(a.Package, b.Package),
			cmp.Compare(a.Vulnerability.GetId(), b.Vulnerability.GetId()),
		)
	})

