   128			if !slices.ContainsFunc(kept.ExploitabilitySignals, func(existing *vex.PackageExploitabilitySignal) bool {
   129				return existing.Plugin == signal.Plugin &&
   130					existing.Justification == signal.Justification &&
   131					existing.MatchesAllVulns == signal.MatchesAllVulns &&
   132					slices.Equal(existing.VulnIdentifiers, signal.VulnIdentifiers)
   133			}) {
   134				kept.ExploitabilitySignals = append(kept.ExploitabilitySignals, signal)
   135			}
   136		}
   137	}
   138	
   139	func mergeRelatedLocation(pkg *extractor.Package, candidate location.Location) {
   140		if candidate.File == nil {
   141			return
   142		}
   143		if pkg.Location.Descriptor != nil && sameLocation(*pkg.Location.Descriptor, candidate) {
   144			return
   145		}
   146		if slices.ContainsFunc(pkg.Location.Related, func(existing location.Location) bool {
   147			return sameLocation(existing, candidate)
   148		}) {
   149			return
   150		}
   151	
   152		pkg.Location.Related = append(pkg.Location.Related, candidate)
   153	}
   154	
   155	func sameLocation(a, b location.Location) bool {
   156		if a.File == nil || b.File == nil {
   157			return a.File == nil && b.File == nil
   158		}
   159	
   160		return a.File.Path == b.File.Path && a.File.LineNumber == b.File.LineNumber
   161	}
   162	
   163	func mergeUnique(a, b []string) []string {
   164		result := slices.Clone(a)
   165		for _, value := range b {
   166			if !slices.Contains(result, value) {
   167				result = append(result, value)
   168			}
   169		}
   170	
   171		return result
   172	}
   173	
   174	func dedupPackageVulns(vulns []*inventory.PackageVuln) []*inventory.PackageVuln {
   175		if len(vulns) == 0 {
   176			return vulns
   177		}
   178	
   179		type vulnIdentity struct {
   180			pkg    packageIdentity
   181			vulnID string
   182		}
   183	
   184		uniqueVulns := make(map[vulnIdentity]*inventory.PackageVuln, len(vulns))
   185		for _, vuln := range vulns {
   186			identity := vulnIdentity{
   187				pkg:    identityOf(vuln.Package),
   188				vulnID: vuln.Vulnerability.GetId(),
   189			}
   190	
   191			kept, ok := uniqueVulns[identity]
   192			if !ok {
   193				uniqueVulns[identity] = vuln
   194				continue
   195			}
   196	
   197			kept.Plugins = mergeUnique(kept.Plugins, vuln.Plugins)
   198			for _, signal := range vuln.ExploitabilitySignals {
   199				if !slices.ContainsFunc(kept.ExploitabilitySignals, func(existing *vex.FindingExploitabilitySignal) bool {
   200					return existing.Plugin == signal.Plugin && existing.Justification == signal.Justification
   201				}) {
   202					kept.ExploitabilitySignals = append(kept.ExploitabilitySignals, signal)
   203				}
   204			}
   205		}
   206	
   207		result := slices.Collect(maps.Values(uniqueVulns))
   208		slices.SortFunc(result, func(a, b *inventory.PackageVuln) int {
   209			return cmp.Or(
   210				inventorySort(a.Package, b.Package),
   211				cmp.Compare(a.Vulnerability.GetId(), b.Vulnerability.GetId()),
   212			)
   213		})
   214	
   215		return result
   216	}
